+      () async {
+    await stubSleep();
+    final io = FakeCliIO();
+
+    final exitCode = await cli(alwaysAuthError(), io).runHeadless('say hi');
+
+    expect(exitCode, 1);
+    expect(io.out.toString(), contains('error:'));
+    expect(io.out.toString(), contains('401 unauthorized'));
