+StreamFunction diesOnceThenCompletes() {
+  var calls = 0;
+  return (model, context, {cancelToken}) {
+    final n = ++calls;
+    final stream = AssistantMessageEventStream();
+    scheduleMicrotask(() {
+      if (n == 1) {
+        final empty = testAssistant();
