AssistantMessage snap(String text) => AssistantMessage(
  content: [TextContent(text: text)],
  api: 'a',
  provider: 'p',
  model: 'm',
  usage: Usage.zero,
  stopReason: StopReason.error,
  errorMessage:
      'SocketException: Connection failed (OS Error: Operation timed out, '
      'errno = 60), address = api.example.com, port = 443',
  timestamp: DateTime.utc(2026),
);

void main() {
  test('roles wrapper re-narrates the resumed-chain exhaustion terminal',
      () async {
    var calls = 0;
    SF dyingStream := (model, context, {cancelToken}) {
      final stream = AssistantMessageEventStream();
      scheduleMicrotask(() {
        calls++;
        final part = AssistantMessage(
          content: [TextContent(text: 'part $calls')],
          api: 'a',
          provider: 'p',
          model: 'm',
          usage: Usage.zero,
          stopReason: StopReason.stop,
          timestamp: DateTime.utc(2026),
        );
        stream
          ..push(StartEvent(partial: part))
          ..push(TextStartEvent(contentIndex: 0, partial: part))
          ..push(TextDeltaEvent(contentIndex: 0, delta: 'x', partial: part))
          ..push(TextEndEvent(contentIndex: 0, content: 'x', partial: part))
          ..push(ErrorEvent(reason: StopReason.error, error: snap('part')))
          ..end();
      });
      return stream;
    };
    final entry = ChainEntry(
      model: Model(id: 'm', api: 'a', provider: 'p', baseUrl: 'u'),
      keyRing: ApiKeyRing(
        baseName: 'K',
        credentials: [ApiKeyCredential('K', 'sk-test')],
      ),
      streamForKey: (_, __, ___) => transientRetryStreamFunction(dyingStream),
    );
    final wrapper = FallbackStreamFunction(
      entries: [entry],
      now: () => DateTime.utc(2026),
      jitterFraction: () => 1.0,
      sleeper: (delay, token) async => true,
    );
    final events = await wrapper
        .call(Model(id: 'm', api: 'a', provider: 'p', baseUrl: 'u'),
            const Context(messages: []))
        .toList();
    final terminal = events.whereType<ErrorEvent>().last;
    // ignore: avoid_print
    print('CALLS: $calls');
    // ignore: avoid_print
    print('TERMINAL REASON: ${terminal.reason}');
    // ignore: avoid_print
    print('TERMINAL MESSAGE: ${terminal.error.errorMessage}');
  });
}
