  /// stack is empty (no key configured).
  static ApiKeyRing? fromSecrets(
    Map<String, String> secrets,
    String baseName, {
    int? startIndex,
    DateTime Function()? now,
  }) {
    final stack = collectKeyStack(secrets, baseName);
    if (stack.isEmpty) return null;
