+    final exitCode = await cli(diesOnceThenCompletes(), io).runHeadless(
+      'say hi',
+    );
+
+    expect(exitCode, 0, reason: 'the turn survived the dead connection');
+    expect(io.out.toString(), contains('partial answer'));
