+  test('headless: the retry is visible as a [net] notice, never silent',
+      () async {
+    await stubSleep();
+    final io = FakeCliIO();
+    final reasons = <String>[];
+    transientRetryNotice = (attempt, maxAttempts, delay, reason) {
+      reasons.add(reason);
+    };
