+          );
+      } else {
+        final empty = testAssistant();
+        final tail = testAssistant(
+          content: [const TextContent(text: 'tail of the answer')],
+        );
+        stream
+          ..push(StartEvent(partial: empty))
+          ..push(TextStartEvent(contentIndex: 0, partial: empty))
+          ..push(
